    if (!validJwk(J.sigPub) || !validJwk(J.encPub)) return err(400, 'keys', 'مفاتيح غير صالحة');
    if (env.REG_KEY && J.regKey !== env.REG_KEY) return err(403, 'regkey', 'مفتاح التسجيل غير صحيح');
